//! 🤝️ Actual original Host input and guest root/ledger allocations conserve each issued turn.
use semio_framework_actor::retained_turn::{ActorGuestPhase,OriginalActorInput,RetainedTurnInput};
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
#[path="../../../../../🛍️products/💻️os/🔨️modules/🔌️plugin/⚛️reactor/🎟️context/🦀️.rs"]
mod guest_context;
fn grant(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_public_actor_paired_admission_retains_exact_host_input_and_native_guest_births(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:grant(&fixture["originalGrant"])};let mut source:Vec<u8>=Vec::with_capacity(97);source.extend_from_slice(&[81;7]);let pointer=source.as_ptr();let(mut host,heap)=observe(||OriginalActorInput::new(source,incoming).ok().unwrap());assert_eq!(heap,(0,0));let mut guest=guest_context::OriginalActorContext::new((),incoming).ok().unwrap();let mut births=0;for index in 0..5{if index>0{host.receive_next_issued(incoming).unwrap()}let mut policy=grant(if index==4{&fixture["bodyPolicy"]}else{&fixture["guestPolicy"]});if index==0{policy.maximum_capacity_bytes=0}let checked=host.checkout_guest(policy).unwrap().unwrap();assert!(host.checkout_guest(policy).is_err());let(admission,heap)=observe(||guest.admit_step(checked).unwrap());assert_eq!(heap,(admission.progress.retained_capacity_bytes,0));births+=admission.progress.retained_capacity_bytes;let mut progress=admission.progress;let phase=if index==4{assert!(admission.ready);let mut recipient=RetainedCloneProgress::default();let mut target=[0;7];let(_,heap)=observe(||{let mut cx=guest.borrow_context(checked,semio_framework_job::StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us).unwrap();target.copy_from_slice(host.original().unwrap());cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap()});assert_eq!(heap,(0,0));assert_eq!(target,[81;7]);progress=recipient;ActorGuestPhase::Dispatched}else if admission.ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending};let receipt=checked.return_original(progress).unwrap();host.receive_guest(receipt,phase).unwrap();assert!(host.receive_guest(receipt,phase).is_err());assert_eq!(host.original().unwrap().as_ptr(),pointer);assert_eq!(progress.copied_items,fixture["spent"][index]["items"].as_u64().unwrap()as usize);assert_eq!(progress.copied_bytes,fixture["spent"][index]["copy"].as_u64().unwrap()as usize);assert_eq!(progress.retained_capacity_bytes,fixture["spent"][index]["capacity"].as_u64().unwrap()as usize);let parent=host.return_actor_turn().unwrap();assert!(host.return_actor_turn().is_err());incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};}assert_eq!(serde_json::to_value(incoming.grant).unwrap(),serde_json::json!({"maximumItems":29,"maximumCopyBytes":25,"maximumCapacityBytes":3904,"maximumReleaseBytes":4096,"maximumDepth":8}));assert_eq!(births,192);let source=host.take_dispatched_input().unwrap().unwrap();assert_eq!(source.as_ptr(),pointer);host.receive_next_issued(incoming).unwrap();let close=grant(&fixture["closePolicy"]);let checked=host.checkout_guest(close).unwrap().unwrap();let(_,heap)=observe(||drop(source));assert_eq!(heap,(0,97));host.receive_guest(checked.return_original(RetainedCloneProgress{copied_items:1,released_bytes:97,..Default::default()}).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};guest.take_input().unwrap();let mut released=0;let mut turns=0;while !guest.terminal_is_empty(){host.receive_next_issued(incoming).unwrap();let checked=host.checkout_guest(close).unwrap().unwrap();let(step,heap)=observe(||guest.close_step(checked).unwrap());let progress=step.progress();assert_eq!(heap,(0,progress.released_bytes));released+=progress.released_bytes;host.receive_guest(checked.return_original(progress).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};turns+=1;assert!(turns<16)}assert_eq!(released,births);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));eprintln!("[DEBUG] actual paired Host source97 pointer={pointer:p} guest root64 ledger128 deniesheap0 bodycopy7,one original guest checkout and Actor return per epoch,finite original32items no renewal,source97 and guest192 physical releases funded in separate turns terminalDrop0");}

#[test]
fn original_public_actor_guest_call_returns_actual_failed_body_receipt_and_paid_same_context_close(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:grant(&fixture["originalGrant"])};let mut source:Vec<u8>=Vec::with_capacity(97);source.extend_from_slice(&[81;7]);let pointer=source.as_ptr();let mut host=OriginalActorInput::new(source,incoming).ok().unwrap();let mut guest=guest_context::OriginalActorContextSlot::empty();let mut capacity=0;for index in 0..6{if index!=0{host.receive_next_issued(incoming).unwrap()}let mut policy=grant(if index==5{&fixture["bodyPolicy"]}else{&fixture["guestPolicy"]});if index<2{policy.maximum_capacity_bytes=0}let checked=host.checkout_guest(policy).unwrap().unwrap();let mut recipient=RetainedCloneProgress::default();let(receipt,phase,heap)=if index==5{let(call,heap)=observe(||guest.dispatch_step(checked,semio_framework_job::StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,|cx|{let mut target=[0;7];target.copy_from_slice(host.original().unwrap());assert_eq!(target,[81;7]);cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap();Err::<(),_>("original semantic refusal")}));assert!(matches!(call.result,Err(guest_context::OriginalActorCallError::Semantic("original semantic refusal"))));assert_eq!(call.receipt_spent,recipient);assert_eq!(call.receipt_spent,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});(call.receipt().unwrap(),ActorGuestPhase::Dispatched,heap)}else{let(call,heap)=observe(||guest.admit_step(checked));let receipt=call.receipt().unwrap();let phase=if call.result.unwrap().ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending};(receipt,phase,heap)};assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));capacity+=receipt.spent.retained_capacity_bytes;host.receive_guest(receipt,phase).unwrap();assert_eq!(host.original().unwrap().as_ptr(),pointer);let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};}assert_eq!(capacity,192);assert_eq!(incoming.grant.maximum_items,28);assert_eq!(incoming.grant.maximum_copy_bytes,25);assert_eq!(incoming.grant.maximum_capacity_bytes,3904);let source=host.take_dispatched_input().unwrap().unwrap();host.receive_next_issued(incoming).unwrap();let close=grant(&fixture["closePolicy"]);let checked=host.checkout_guest(close).unwrap().unwrap();let(_,heap)=observe(||drop(source));assert_eq!(heap,(0,97));host.receive_guest(checked.return_original(RetainedCloneProgress{copied_items:1,released_bytes:97,..Default::default()}).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};let mut released=0;let mut turns=0;while !guest.terminal_is_empty(){host.receive_next_issued(incoming).unwrap();let checked=host.checkout_guest(close).unwrap().unwrap();let(call,heap)=observe(||guest.close_step(checked));let receipt=call.receipt().unwrap();assert!(call.result.is_ok());assert_eq!(heap,(receipt.spent.retained_capacity_bytes,receipt.spent.released_bytes));released+=receipt.spent.released_bytes;host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};turns+=1;assert!(turns<16)}assert_eq!(released,capacity);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));eprintln!("[DEBUG] actual caller failure keeps original Host source97 pointer={pointer:p},same paid root64/ledger128; semantic Err returns exact external items1/copy7,context binding yields and closes separately under original32 item authority; native terminalDrop0");}

#[test]
fn original_public_actor_guest_entry_keeps_same_fault_and_raw_receipts_through_paid_native_publication(){
 use semio_framework_value::FromValue;
 use semio_framework_job::{StepBudget,JobOutcomeView};
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../🛍️products/💻️os/🔨️modules/🔌️plugin/⚛️reactor/🎟️context/🌉️call/🧫️fixtures/🔣️.json")).unwrap();
 let canonical:serde_json::Value=serde_json::from_str(include_str!("../../../../../🔨️modules/⚠️diagnostic/🧫️fixtures/🧯️fault/🔣️.json")).unwrap();
 let row=&canonical["cases"][0];let(original_fault,source_heap)=observe(||semio_framework_diagnostic::Fault::from_value(serde_json::from_value(row["input"].clone()).unwrap()).unwrap());let source_net=source_heap.0.checked_sub(source_heap.1).unwrap();let source_message=original_fault.message.as_ptr();let mut pending_fault=Some(original_fault);
 let mut incoming=RetainedTurnInput{operation:71,generation:3,epoch:19,grant:grant(&fixture["entryOriginalAuthority"])};let(mut host,heap)=observe(||OriginalActorInput::new((),incoming).ok().unwrap());assert_eq!(heap,(0,0));let(mut guest,heap)=observe(guest_context::OriginalActorGuestEntry::new);assert_eq!(heap,(0,0));let mut born=0;let mut released=0;let mut ready=false;
 while !ready{let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,..incoming.grant};let checked=host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||guest.admit_step(checked));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=heap.0;released+=heap.1;let reply=guest_context::OriginalActorAdmissionReply::borrow_original(&call);assert_eq!(reply.input,checked);assert_eq!(reply.spent,call.receipt_spent);assert!(reply.refusal.is_none());ready=reply.ready;host.receive_guest(call.receipt().unwrap(),if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending}).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();}
 let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:7,maximum_capacity_bytes:0,maximum_release_bytes:0,..incoming.grant}).unwrap().unwrap();let mut recipient=Default::default();let original_recipient=&mut recipient as*mut _;let(call,heap)=observe(||guest.dispatch_step(checked,StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us,|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).unwrap();Err::<(),_>(pending_fault.take().unwrap())}));assert_eq!(heap,(0,0));assert!(matches!(call.result,Err(guest_context::OriginalActorEntryFailure::Semantic)));assert_eq!(call.receipt_spent,RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});assert_eq!(guest.original_fault().unwrap().message.as_ptr(),source_message);let fault_pointer=guest.original_fault().unwrap()as*const _;host.receive_guest(call.receipt().unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();
 let mut descriptor=None;let mut turns=0;while descriptor.is_none(){let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:17,..incoming.grant}).unwrap().unwrap();recipient=Default::default();let(call,heap)=observe(||guest.publish_failure_call(checked,StepBudget::new(100,u64::MAX,checked.grant),&mut recipient,semio_framework_job::logical_now_us));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));assert_eq!(&mut recipient as*mut _,original_recipient);born+=heap.0;released+=heap.1;let receipt=call.receipt().unwrap();descriptor=call.result.unwrap();assert_eq!(guest.original_fault().unwrap()as*const _,fault_pointer);assert_eq!(guest.original_fault().unwrap().message.as_ptr(),source_message);host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();turns+=1;assert!(turns<1024);}
 let mut descriptor=descriptor.unwrap();let view=guest.borrow_failure_outcome(&descriptor).unwrap();let payload=match view{JobOutcomeView::Fault{detail,..}=>detail,_=>panic!("original guest fault descriptor required")};let mut bytes=Vec::with_capacity(payload.len());for index in 0..payload.page_count(){bytes.extend_from_slice(payload.page(index).unwrap())}assert_eq!(serde_json::from_slice::<serde_json::Value>(&bytes).unwrap(),row["expected"]);drop(bytes);
 let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,..incoming.grant}).unwrap().unwrap();let(step,heap)=observe(||descriptor.acknowledge(checked.grant));assert_eq!(heap,(0,0));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(descriptor.is_acknowledged());host.receive_guest(checked.return_original(step.progress()).unwrap(),ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();assert_eq!(observe(||drop(descriptor)).1,(0,0));host.take_dispatched_input().unwrap();
 let mut closes=0;while !guest.terminal_is_empty(){let checked=host.checkout_guest(RetainedCloneGrant{maximum_items:1,..incoming.grant}).unwrap().unwrap();let(call,heap)=observe(||guest.close_step(checked));assert_eq!(heap,(call.receipt_spent.retained_capacity_bytes,call.receipt_spent.released_bytes));born+=heap.0;released+=heap.1;let receipt=call.receipt().unwrap();assert!(call.result.is_ok());host.receive_guest(receipt,ActorGuestPhase::Dispatched).unwrap();let parent=host.return_actor_turn().unwrap();incoming=RetainedTurnInput{epoch:incoming.epoch+1,grant:parent.remaining,..incoming};host.receive_next_issued(incoming).unwrap();closes+=1;assert!(closes<256);}
 assert_eq!(released,born+source_net);assert_eq!(observe(||drop(guest)).1,(0,0));assert_eq!(observe(||drop(host)).1,(0,0));eprintln!("[DEBUG] actual original guest entry71/3 raw failed1/copy7 recipient={original_recipient:p} originalFault={fault_pointer:p} message={source_message:p} publicationTurns={turns} closeTurns={closes} original2048 item authority no renewal nativeBorn={born} callerFaultNet={source_net} paidReleased={released} terminalDrop0; caller Fault birth remains separate");
}
